import React from 'react';
import './Dashboard.css'; // Import CSS for styling

const WorkingDashboard = () => {
  return (
    <div className="dashboard-layout">
      {/* Sidebar */}
      <div className="sidebar">
        <div className="logo-container">
          <img src={companyLogo} alt="Company Logo" className="company-logo" />
        </div>
        <nav className="nav-links">
          <a href="#customer" className="nav-link">Customer</a>
          <a href="#working" className="nav-link active">Working</a>
          <a href="#attendance" className="nav-link">Attendance</a>
        </nav>
      </div>

      {/* Main Content */}
      <div className="main-content">
        <header className="header">
          <h1 className="company-title">CadMax Projects Pvt. Ltd.</h1>
        </header>

        {/* Select Department Box */}
        <div className="select-department-box">
          <label htmlFor="select-department" className="select-label">Select Department</label>
          <select id="select-department" className="select-department">
            <option>Select a department...</option>
            <option>HR</option>
            <option>Finance</option>
            <option>Engineering</option>
            <option>Sales</option>
          </select>
        </div>
      </div>

      {/* Profile Logo and Text at the Top Right */}
      <div className="top-right">
        {/* Profile Logo as emoji */}
        <span className="profile-text">Someone</span>
        <div className="profile-logo">
          <span>👤</span> {/* Using the emoji directly */}
        </div>
      </div>
    </div>
  );
};

export default WorkingDashboard;
